We proceed by inspecting the contribution of each group of interface entities. For vertex nodes, it follows from the Kronecker delta property of the multiscale functions that $\Phi^{\text{AM}}_{\text{V}} \mathbf{1}_{\text{V}} = I_{\text{VV}} \mathbf{1}_{\text{V}} = \mathbf{1}_{\text{V}}$.

    For edge nodes, the partition of unity property is satisfied if
    \begin{equation*}
        \Phi^{\text{AM}}_{\text{E}} \mathbf{1}_{\text{V}} = -\tilde{A}_{\text{EE}}^{-1} A_{\text{EV}} \mathbf{1}_{\text{V}} = \mathbf{1}_{\text{E}},
    \end{equation*}
    or equivalently
    \begin{equation*}
        \tilde{A}_{\text{EE}} \mathbf{1}_{\text{E}} + A_{\text{EV}} \mathbf{1}_{\text{V}} = \mathbf{0}.
    \end{equation*}
    Replacing the definition of $\tilde{A}_{\text{EE}}$ from \cref{eq:ams_diagonal_blocks}, we have
    \begin{align*}
        \tilde{A}_{\text{EE}} \mathbf{1}_{\text{E}} + A_{\text{EV}} \mathbf{1}_{\text{V}}
        &= A_{\text{EE}} \mathbf{1}_{\text{E}} + \mathop{\operator@font diag}\nolimits \left( A_{\text{EI}} \mathbf{1}_{\text{I}} \right) \mathbf{1}_{\text{E}} + \mathop{\operator@font diag}\nolimits \left( A_{\text{EF}} \mathbf{1}_{\text{F}} \right) \mathbf{1}_{\text{E}} + A_{\text{EV}} \mathbf{1}_{\text{V}} \\
        &= A_{\text{EE}} \mathbf{1}_{\text{E}} + A_{\text{EI}} \mathbf{1}_{\text{I}} + A_{\text{EF}} \mathbf{1}_{\text{F}} + A_{\text{EV}} \mathbf{1}_{\text{V}},
    \end{align*}
    where the $\mathop{\operator@font diag}\nolimits$ operator can be removed as the multiplication by the vector of ones retrieves the original vector that was expanded into a diagonal matrix. The term above is the sum of the entries in each row of the system matrix related to edge nodes. Since the problem is discretized using piecewise linear finite elements, the sum of the entries of a row corresponding to a node not on the Dirichlet boundary is zero. Therefore, we have a partition of unity for edge nodes.

    We may proceed similarly for face nodes:
    \begin{align*}
        \tilde{A}_{\text{FF}} \mathbf{1}_{\text{F}} + A_{\text{FV}} \mathbf{1}_{\text{V}} + A_{\text{FE}} \Phi^{\text{AM}}_{\text{E}} \mathbf{1}_{\text{V}}
        &= A_{\text{FF}} \mathbf{1}_{\text{F}} + \mathop{\operator@font diag}\nolimits \left( A_{\text{FI}} \mathbf{1}_{\text{I}} \right) \mathbf{1}_{\text{F}} + A_{\text{FV}} \mathbf{1}_{\text{V}} + A_{\text{FE}} \mathbf{1}_{\text{E}} \\
        &= A_{\text{FF}} \mathbf{1}_{\text{F}} + A_{\text{FI}} \mathbf{1}_{\text{I}} + A_{\text{FV}} \mathbf{1}_{\text{V}} + A_{\text{FE}} \mathbf{1}_{\text{E}} \\
        &= \mathbf{0}.
    \end{align*}
    Thus, the partition of unity property is satisfied for face nodes as well.

    Repeating the same steps for the interior nodes, we have
    \begin{align*}
        A_{\text{II}} \mathbf{1}_{\text{I}} + \left( A_{\text{IV}} \Phi^{\text{AM}}_{\text{V}} + A_{\text{IE}} \Phi^{\text{AM}}_{\text{E}} + A_{\text{IF}} \Phi^{\text{AM}}_{\text{F}} \right) \mathbf{1}_{\text{V}}
        &= A_{\text{II}} \mathbf{1}_{\text{I}} + A_{\text{IV}} \mathbf{1}_{\text{V}} + A_{\text{IE}} \mathbf{1}_{\text{E}} + A_{\text{IF}} \mathbf{1}_{\text{F}} \\
        &= \mathbf{0}.
    \end{align*}
    Hence $\Phi^{\text{AM}}_{\text{I}} \mathbf{1}_{\text{V}} = \mathbf{1}_{\text{I}}$.

We begin by noticing that assumptions (A1) and (A2) are satisfied by definition of the prolongation operator, as $\Phi^{\text{AM}}_{\text{V}} = I_{\text{VV}}$ and the RBC problems are solved on the space of piecewise linear functions. Additionally, from \cref{lemma:ams_pou}, we have that the partition of unity property is met, thus ensuring that assumption (A4) is true.

    To verify assumption (A3), we recall that the submatrices $\tilde{A}_{\text{EE}}$, $\tilde{A}_{\text{FF}}$, and $A_{\text{II}}$ are block diagonal. For a given coarse basis function $\Phi_j$, we may group the diagonal blocks related to nodes inside and outside $\omega_j$. On the edges, we have
    \begin{align*}
        \tilde{A}_{\text{EE}} \Phi_{\text{E}, j}^{\text{AM}} &= -A_{\text{EV}, j} \\
        \implies
        \begin{bmatrix}
            \tilde{A}_{\text{EE}}^{\omega_j} & 0 \\
            0 & \tilde{A}_{\text{EE}}^{\Omega \setminus \omega_j}
        \end{bmatrix}
        \begin{bmatrix}
            \Phi_{\text{E}, j}^{\text{AM}, \omega_j} \\
            \Phi_{\text{E}, j}^{\text{AM}, \Omega \setminus \omega_j}
        \end{bmatrix} &=
        \begin{bmatrix}
            -A_{\text{EV}, j}^{\omega_j} \\
            -A_{\text{EV}, j}^{\Omega \setminus \omega_j}
        \end{bmatrix},
    \end{align*}
    where $A_{\text{EV}, j}$ is the $j$-th column of $A_{\text{EV}}$. For nodes in $\Omega \setminus \omega_j$,
    \begin{equation*}
        \Phi_{\text{E}, j}^{\text{AM}, \Omega \setminus \omega_j} = -\left( \tilde{A}_{\text{EE}}^{\Omega \setminus \omega_j} \right)^{-1} A_{\text{EV}, j}^{\Omega \setminus \omega_j}.
    \end{equation*}
    Since no node outside $\omega_j$ is connected to the coarse node $x_j$, $A_{\text{EV}, j}^{\Omega \setminus \omega_j} = 0$ and, as a consequence, $\Phi_{\text{E}, j}^{\text{AM}, \Omega \setminus \omega_j} = 0$. Therefore, $\Phi_{\text{E}, j}^{\text{AM}}$ has nonzero values only in $\omega_j$. We may proceed similarly for the remaining components $\Phi_{\text{F}, j}^{\text{AM}}$ and $\Phi_{\text{I}, j}^{\text{AM}}$ to obtain the same result and verify that $\mathop{\operator@font supp}\nolimits{\Phi_j} \subset \overline{\omega}_j$. Moreover, as a consequence of the Kronecker delta property of $\Phi_j$ and the fact that the right-hand side of the local problem for nodes on $\partial \omega_j$ is zero, we have that $\Phi_j(x) = 0$ on $\partial \omega_j$ and thus assumption (A6) is also satisfied.

    Finally, for assumption (A5), we invoke the fact that, for any piecewise constant coefficient function, if no element $K \in \mathcal{T}^H$ has an obtuse angle, then the energy-minimizing extension of the boundary data $\Phi_{j, \Gamma}$ respects the discrete maximum principle; cf. \cite[Remark~4.2]{GRAHAM2007MSPDES}. From the boundary conditions of the RBC problem, the maximum value of $\Phi_j$ is attained at the coarse node $x_j$ and is equal to 1. Therefore, $|| \Phi_j ||_{L_{\infty}(\Omega)} = 1$. Additionally, as previously shown, the minimum value is attained on $\partial \omega_j$ and is equal to 0. Hence, $0 \leq \Phi_{j} \leq 1$.

As in the proof of \cref{lemma:ams_pou}, it suffices to verify that the row sums of the submatrices coupling the slab region to the remaining nodes vanish. For a slab edge $e'$, the definition of $\tilde{A}_{e' e'}$ in \cref{eq:ams_slab_bf_edge} yields
    \begin{align*}
        \tilde{A}_{e' e'} \mathbf{1}_{e'} + A_{e' \text{V}_e} \mathbf{1}_{\text{V}_e}
        &= A_{e' e'} \mathbf{1}_{e'} + A_{e' e^{\ast}} \mathbf{1}_{e^{\ast}} + A_{e' \text{V}_e} \mathbf{1}_{\text{V}_e} \\
        &= \begin{bmatrix}
            A_{e' e^{\ast}} & A_{e' e'} & A_{e' \text{V}_{e}}
        \end{bmatrix} \mathbf{1} \\
        &= \mathbf{0},
    \end{align*}
    where the second equality expresses the row sums of $A$ over the rows associated with $e'$, which vanish for piecewise linear finite elements away from the Dirichlet boundary; cf. \cref{re:ams_pou}. Analogously, for a face slab $f'$, using $\Phi^{\text{AM}}_{\text{E}_f} \mathbf{1}_{\text{V}} = \mathbf{1}_{\text{E}_f}$, one obtains
    \begin{align*}
        \tilde{A}_{f' f'} \mathbf{1}_{f'} + A_{f' \text{E}_f} \mathbf{1}_{\text{E}_f} + A_{f' \text{V}_f} \mathbf{1}_{\text{V}_f}
        &= A_{f' f'} \mathbf{1}_{f'} + A_{f' f^{\ast}} \mathbf{1}_{f^{\ast}} + A_{f' \text{E}_f} \mathbf{1}_{\text{E}_f} + A_{f' \text{V}_f} \mathbf{1}_{\text{V}_f} \\
        &= \begin{bmatrix}
            A_{f' f^{\ast}} & A_{f' f} & A_{f' \text{E}_{f}} & A_{f' \text{V}_{f}}
        \end{bmatrix} \mathbf{1} \\
        &= \mathbf{0}.
    \end{align*}
    Finally, since $\Gamma_i \subset \Gamma_i'$, partitioning the rows of $\Phi^{\text{AM}}_{\Gamma_i'}$ into those associated with $\Gamma_i$ and $\Gamma_i' \setminus \Gamma_i$ yields
    \begin{align*}
        \Phi^{\text{AM}}_{\Gamma_i'} \mathbf{1}_{\text{V}} &= \mathbf{1}_{\Gamma_i'} \\
        \implies
        \begin{bmatrix}
            \Phi^{\text{AM}}_{\Gamma_i} \\
            \Phi^{\text{AM}}_{\Gamma_i' \setminus \Gamma_i}
        \end{bmatrix} \mathbf{1}_{\text{V}}
        &=
        \begin{bmatrix}
            \mathbf{1}_{\Gamma_i} \\
            \mathbf{1}_{\Gamma_i' \setminus \Gamma_i}
        \end{bmatrix} \\
        \implies
        \Phi^{\text{AM}}_{\Gamma_i} \mathbf{1}_{\text{V}} &= \mathbf{1}_{\Gamma_i}.
    \end{align*}
